/**
* Local implementation of zeta for positive integer arguments.
*/
static double local_zeta( const double s ) {
	int32_t idx;
	int32_t si = (int32_t)s;
	
	if ( s <= 0.0 ) {
		return NAN;
	}
	if ( s == 1.0 ) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	
	if ( si % 2 == 0 ) {
		idx = ( si / 2 ) - 1;
		if ( idx >= 0 && idx < 56 ) {
			return ZETA_EVEN[ idx ];
		}
		return 1.0;
	}
	idx = ( ( si - 1 ) / 2 ) - 1;
	if ( idx >= 0 && idx < 56 ) {
		return ZETA_ODD[ idx ];
	}
	return 1.0;
}

/**
* Evaluates a polynomial using Horner's rule.
*/
static double evalpoly( const double *coeffs, const int32_t len, const double x ) {
	double result;
	int32_t i;

	result = coeffs[len - 1];
	for ( i = len - 2; i >= 0; i-- ) {
		result = result * x + coeffs[i];
	}
	return result;
}

// Polynomial coefficients for polycotpi (n=3 to n=12)
static const double POLY3[] = { -2.0, -4.0 };
static const double POLY4[] = { 16.0, 8.0 };
static const double POLY5[] = { -16.0, -88.0, -16.0 };
static const double POLY6[] = { 272.0, 416.0, 32.0 };
static const double POLY7[] = { -272.0, -2880.0, -1824.0, -64.0 };
static const double POLY8[] = { 7936.0, 24576.0, 7680.0, 128.0 };
static const double POLY9[] = { -7936.0, -137216.0, -185856.0, -31616.0, -256.0 };
static const double POLY10[] = { 353792.0, 1841152.0, 1304832.0, 128512.0, 512.0 };
static const double POLY11[] = { -353792.0, -9061376.0, -21253376.0, -8728576.0, -518656.0, -1024.0 };
static const double POLY12[] = { 22368256.0, 175627264.0, 222398464.0, 56520704.0, 2084864.0, 2048.0 };

// Global coefficient table for n > 12 (computed lazily)
static double **g_poly_table = NULL;
static int32_t g_poly_table_size = 0;

/**
* Calculate derivatives table for polycotpi (n > 12)
* This matches the JavaScript calculateDerivatives function exactly
*/
static void calculate_poly_table( int32_t n ) {
	int32_t i, j, k;
	int32_t offset, so, mo, ncols, noffset, mcols, co;
	double **new_table;
	int32_t new_size;
	
	if ( n <= 12 ) {
		return;
	}
	
	// Initialize table if needed
	if ( g_poly_table == NULL ) {
		g_poly_table = (double **)malloc( sizeof( double * ) );
		if ( g_poly_table == NULL ) return;
		g_poly_table[0] = (double *)malloc( sizeof( double ) );
		if ( g_poly_table[0] == NULL ) { free( g_poly_table ); g_poly_table = NULL; return; }
		g_poly_table[0][0] = -1.0;
		g_poly_table_size = 1;
	}
	
	// Grow table to size n
	new_size = n;
	new_table = (double **)realloc( g_poly_table, new_size * sizeof( double * ) );
	if ( new_table == NULL ) return;
	g_poly_table = new_table;
	
	// Build rows using the same algorithm as JavaScript
	for ( i = g_poly_table_size - 1; i < n - 1; i++ ) {
		offset = i & 1;
		so = i + 2;
		mo = so - 1;
		ncols = ( mo - offset ) / 2;
		noffset = offset ? 0 : 1;
		mcols = ( mo + 1 - noffset ) / 2;
		
		g_poly_table[ i + 1 ] = (double *)calloc( (size_t)( mcols + 1 ), sizeof( double ) );
		if ( g_poly_table[ i + 1 ] == NULL ) return;
		
		for ( j = 0; j <= ncols; j++ ) {
			co = 2 * j + offset;
			k = ( co + 1 ) / 2;
			g_poly_table[ i + 1 ][ k ] += ( (double)( co - so ) * g_poly_table[ i ][ j ] ) / (double)( so - 1 );
			if ( co ) {
				k = ( co - 1 ) / 2;
				g_poly_table[ i + 1 ][ k ] += ( (double)( -co ) * g_poly_table[ i ][ j ] ) / (double)( so - 1 );
			}
		}
	}
	
	g_poly_table_size = new_size;
}

/**
* n'th derivative of cot(pi*x)
* This matches the JavaScript polycotpi function exactly
*/
static double polycotpi( const int32_t n, const double x, const double xc ) {
	double s, c, c2;
	double powTerms, out, sum;
	int32_t idx, j;
	
	s = ( stdlib_base_abs( x ) < stdlib_base_abs( xc ) ) ? stdlib_base_sinpi( x ) : stdlib_base_sinpi( xc );
	c = stdlib_base_cospi( x );
	c2 = c * c;

	switch ( n ) {
	case 1:
		return -STDLIB_CONSTANT_FLOAT64_PI / ( s * s );
	case 2:
		return 2.0 * STDLIB_CONSTANT_FLOAT64_PI * STDLIB_CONSTANT_FLOAT64_PI * c / stdlib_base_pow( s, 3.0 );
	case 3:
		return STDLIB_CONSTANT_FLOAT64_PI * STDLIB_CONSTANT_FLOAT64_PI * STDLIB_CONSTANT_FLOAT64_PI * evalpoly( POLY3, 2, c2 ) / stdlib_base_pow( s, 4.0 );
	case 4:
		return STDLIB_CONSTANT_FLOAT64_PI * STDLIB_CONSTANT_FLOAT64_PI * STDLIB_CONSTANT_FLOAT64_PI * STDLIB_CONSTANT_FLOAT64_PI * c * evalpoly( POLY4, 2, c2 ) / stdlib_base_pow( s, 5.0 );
	case 5:
		{
			double pi5 = STDLIB_CONSTANT_FLOAT64_PI;
			int32_t i;
			for ( i = 0; i < 4; i++ ) pi5 *= STDLIB_CONSTANT_FLOAT64_PI;
			return pi5 * evalpoly( POLY5, 3, c2 ) / stdlib_base_pow( s, 6.0 );
		}
	case 6:
		{
			double pi6 = STDLIB_CONSTANT_FLOAT64_PI;
			int32_t i;
			for ( i = 0; i < 5; i++ ) pi6 *= STDLIB_CONSTANT_FLOAT64_PI;
			return pi6 * c * evalpoly( POLY6, 3, c2 ) / stdlib_base_pow( s, 7.0 );
		}
	case 7:
		{
			double pi7 = STDLIB_CONSTANT_FLOAT64_PI;
			int32_t i;
			for ( i = 0; i < 6; i++ ) pi7 *= STDLIB_CONSTANT_FLOAT64_PI;
			return pi7 * evalpoly( POLY7, 4, c2 ) / stdlib_base_pow( s, 8.0 );
		}
	case 8:
		{
			double pi8 = STDLIB_CONSTANT_FLOAT64_PI;
			int32_t i;
			for ( i = 0; i < 7; i++ ) pi8 *= STDLIB_CONSTANT_FLOAT64_PI;
			return pi8 * c * evalpoly( POLY8, 4, c2 ) / stdlib_base_pow( s, 9.0 );
		}
	case 9:
		{
			double pi9 = STDLIB_CONSTANT_FLOAT64_PI;
			int32_t i;
			for ( i = 0; i < 8; i++ ) pi9 *= STDLIB_CONSTANT_FLOAT64_PI;
			return pi9 * evalpoly( POLY9, 5, c2 ) / stdlib_base_pow( s, 10.0 );
		}
	case 10:
		{
			double pi10 = STDLIB_CONSTANT_FLOAT64_PI;
			int32_t i;
			for ( i = 0; i < 9; i++ ) pi10 *= STDLIB_CONSTANT_FLOAT64_PI;
			return pi10 * c * evalpoly( POLY10, 5, c2 ) / stdlib_base_pow( s, 11.0 );
		}
	case 11:
		{
			double pi11 = STDLIB_CONSTANT_FLOAT64_PI;
			int32_t i;
			for ( i = 0; i < 10; i++ ) pi11 *= STDLIB_CONSTANT_FLOAT64_PI;
			return pi11 * evalpoly( POLY11, 6, c2 ) / stdlib_base_pow( s, 12.0 );
		}
	case 12:
		{
			double pi12 = STDLIB_CONSTANT_FLOAT64_PI;
			int32_t i;
			for ( i = 0; i < 11; i++ ) pi12 *= STDLIB_CONSTANT_FLOAT64_PI;
			return pi12 * c * evalpoly( POLY12, 6, c2 ) / stdlib_base_pow( s, 13.0 );
		}
	default:
		break;
	}

	// n > 12: use logarithmic computation with coefficient table
	if ( n / 2 > MAX_SERIES_ITERATIONS ) {
		return NAN;
	}
	
	idx = n - 1;
	
	// Calculate coefficients if needed
	if ( idx >= g_poly_table_size ) {
		calculate_poly_table( n );
	}
	
	if ( g_poly_table == NULL || idx >= g_poly_table_size ) {
		return NAN;
	}
	
	// Evaluate polynomial using Horner's method
	{
		int32_t offset = idx & 1;
		int32_t mo = idx + 1;
		int32_t ncols = ( mo - offset ) / 2;
		
		// Start from highest coefficient
		sum = g_poly_table[ idx ][ ncols ];
		for ( j = ncols - 1; j >= 0; j-- ) {
			sum = sum * c2 + g_poly_table[ idx ][ j ];
		}
		
		// For odd n, multiply by c
		if ( idx & 1 ) {
			sum *= c;
		}
	}
	
	if ( sum == 0.0 ) {
		return sum;
	}
	
	// Use logarithmic computation
	powTerms = (double)( n ) * STDLIB_CONSTANT_FLOAT64_LN_PI;
	
	if ( s == 0.0 ) {
		return ( sum >= 0.0 ) ? STDLIB_CONSTANT_FLOAT64_PINF : STDLIB_CONSTANT_FLOAT64_NINF;
	}
	
	powTerms -= stdlib_base_ln( stdlib_base_abs( s ) ) * (double)( n + 1 );
	powTerms += stdlib_base_gammaln( (double)( n ) ) + stdlib_base_ln( stdlib_base_abs( sum ) );

	if ( powTerms > STDLIB_CONSTANT_FLOAT64_MAX_LN ) {
		return ( sum >= 0.0 ) ? STDLIB_CONSTANT_FLOAT64_PINF : STDLIB_CONSTANT_FLOAT64_NINF;
	}
	
	out = stdlib_base_exp( powTerms ) * stdlib_base_signum( sum );
	
	// Apply sign correction for negative sin
	if ( s < 0.0 && ( ( n + 1 ) & 1 ) ) {
		out *= -1.0;
	}
	
	return out;
}

static double nearzero( const int32_t n, const double x ) {
	double scale, prefix, factorialPart, sum, term;
	int32_t k;

	scale = stdlib_base_factorial( n );
	factorialPart = 1.0;
	prefix = stdlib_base_pow( x, (double)( n + 1 ) );
	if ( prefix == 0.0 ) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	prefix = 1.0 / prefix;

	if ( prefix > 2.0 / STDLIB_CONSTANT_FLOAT64_EPS ) {
		if ( n & 1 ) {
			return ( STDLIB_CONSTANT_FLOAT64_MAX / prefix < scale ) ? STDLIB_CONSTANT_FLOAT64_PINF : prefix * scale;
		}
		return ( STDLIB_CONSTANT_FLOAT64_MAX / prefix < scale ) ? STDLIB_CONSTANT_FLOAT64_NINF : -prefix * scale;
	}

	sum = prefix;
	for ( k = 0; ; ) {
		term = factorialPart * local_zeta( (double)( k + n + 1 ) );
		sum += term;

		if ( stdlib_base_abs( term ) < stdlib_base_abs( sum * STDLIB_CONSTANT_FLOAT64_EPS ) ) {
			break;
		}
		k += 1;
		factorialPart *= ( -x * (double)( n + k ) ) / (double)( k );

		if ( k > MAX_SERIES_ITERATIONS ) {
			return NAN;
		}
	}

	if ( STDLIB_CONSTANT_FLOAT64_MAX / scale < sum ) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	sum *= scale;
	return ( n & 1 ) ? sum : -sum;
}

static double atinfinityplus( const int32_t n, const double x ) {
	double partTerm;
	double term;
	double sum;
	double xsquared;
	double nlx;
	int32_t k;
	int32_t k2;

	if ( n == 1 ) {
		return 1.0 / x;
	}

	nlx = n * stdlib_base_ln( x );
	if ( n + x == x ) {
		if ( nlx < STDLIB_CONSTANT_FLOAT64_MAX_LN && n < 172 ) {
			return ( ( n & 1 ) ? 1.0 : -1.0 ) * stdlib_base_factorial( n - 1 ) * stdlib_base_pow( x, (double)( -n ) );
		}
		return ( ( n & 1 ) ? 1.0 : -1.0 ) * stdlib_base_exp( stdlib_base_gammaln( (double)( n ) ) - ( (double)( n ) * stdlib_base_ln( x ) ) );
	}

	xsquared = x * x;

	if ( n > 172 && (double)( n ) * (double)( n ) > STDLIB_CONSTANT_FLOAT64_MAX_LN ) {
		partTerm = 0.0;
	} else {
		partTerm = stdlib_base_factorial( n - 1 ) * stdlib_base_pow( x, (double)( -n - 1 ) );
	}

	if ( partTerm == 0.0 ) {
		partTerm = stdlib_base_gammaln( (double)( n ) ) - ( (double)( n + 1 ) * stdlib_base_ln( x ) );
		sum = stdlib_base_exp( partTerm + stdlib_base_ln( (double)( n + 2.0*x ) ) - STDLIB_CONSTANT_FLOAT64_LN2 );
		partTerm += stdlib_base_ln( (double)( n * ( n + 1 ) ) ) - STDLIB_CONSTANT_FLOAT64_LN2 - stdlib_base_ln( x );
		partTerm = stdlib_base_exp( partTerm );
	} else {
		sum = partTerm * ( (double)( n ) + 2.0*x ) / 2.0;
		partTerm *= (double)( n * ( n + 1 ) ) / 2.0;
		partTerm /= x;
	}

	if ( sum == 0.0 ) {
		return sum;
	}

	for ( k = 1; ; ) {
		term = partTerm * stdlib_base_bernoulli( (double)( k * 2 ) );
		sum += term;

		if ( stdlib_base_abs( term / sum ) < STDLIB_CONSTANT_FLOAT64_EPS ) {
			break;
		}

		k += 1;
		k2 = 2 * k;
		partTerm *= (double)( ( n + k2 - 2 ) * ( n - 1 + k2 ) );
		partTerm /= (double)( ( k2 - 1 ) * k2 );
		partTerm /= xsquared;

		if ( k > MAX_SERIES_ITERATIONS ) {
			return NAN;
		}
	}

	if ( ( n - 1 ) & 1 ) {
		sum = -sum;
	}
	return sum;
}

static double attransitionplus( const int32_t n, const double x ) {
	double minusMplus1;
	double zpows;
	double lnterm;
	int32_t iter;
	double sum0;
	double d4d;
	double N;
	int32_t m;
	int32_t k;
	double z;

	d4d = 0.4 * DIGITS_BASE10;
	N = d4d + ( 4.0 * n );
	m = n;
	iter = (int32_t)( N - stdlib_base_trunc( x ) );

	if ( iter > MAX_SERIES_ITERATIONS ) {
		return NAN;
	}

	minusMplus1 = -(double)( m + 1 );
	z = x;
	sum0 = 0.0;
	zpows = 0.0;

	if ( stdlib_base_ln( z + (double)( iter ) ) * minusMplus1 > -STDLIB_CONSTANT_FLOAT64_MAX_LN ) {
		for ( k = 1; k <= iter; k++ ) {
			zpows = stdlib_base_pow( z, minusMplus1 );
			sum0 += zpows;
			z += 1.0;
		}
		sum0 *= stdlib_base_factorial( n );
	} else {
		for ( k = 1; k <= iter; k++ ) {
			lnterm = ( stdlib_base_ln( z ) * minusMplus1 ) + stdlib_base_gammaln( (double)( n + 1 ) );
			sum0 += stdlib_base_exp( lnterm );
			z += 1.0;
		}
	}

	if ( ( n - 1 ) & 1 ) {
		sum0 = -sum0;
	}
	return sum0 + atinfinityplus( n, z );
}

/**
* Evaluates the polygamma function.
*/
double stdlib_base_polygamma( const int32_t n, const double x ) {
	double result, xSmallLimit;
	double z;

	if ( stdlib_base_is_nan( x ) || n < 0 ) {
		return NAN;
	}

	if ( n == 0 ) {
		return stdlib_base_digamma( x );
	}

	if ( n == 1 ) {
		return stdlib_base_trigamma( x );
	}

	if ( x < 0.0 ) {
		if ( stdlib_base_floor( x ) == x ) {
			if ( ( (int32_t)stdlib_base_trunc( x ) ) & 1 ) {
				return STDLIB_CONSTANT_FLOAT64_PINF;
			}
			return NAN;
		}
		// Reflection formula: psi^{(n)}(-x) = (-1)^{n+1} * psi^{(n)}(x+1) + (-1)^n * pi * cot^{(n)}(pi*x)
		// For x < 0, we use: psi^{(n)}(x) = psi^{(n)}(1-x) + (-1)^n * pi * cot^{(n)}(pi*x)
		// Note: the cot derivative term already includes (-1)^n in its formula
		z = 1.0 - x;
		result = stdlib_base_polygamma( n, z ) + STDLIB_CONSTANT_FLOAT64_PI * polycotpi( n, z, x );
		// The sign flip comes from the reflection formula
		return ( n & 1 ) ? -result : result;
	}

	xSmallLimit = ( 5.0 / n < 0.25 ) ? 5.0 / n : 0.25;

	if ( x < xSmallLimit ) {
		return nearzero( n, x );
	}

	if ( x > ( 0.4 * DIGITS_BASE10 ) + ( 4.0 * n ) ) {
		return atinfinityplus( n, x );
	}

	if ( x == 1.0 ) {
		return ( ( n & 1 ) ? 1.0 : -1.0 ) * stdlib_base_factorial( n ) * local_zeta( (double)( n + 1 ) );
	}

	if ( x == 0.5 ) {
		result = ( ( n & 1 ) ? 1.0 : -1.0 ) * stdlib_base_factorial( n ) * local_zeta( (double)( n + 1 ) );
		if ( stdlib_base_abs( result ) >= stdlib_base_ldexp( STDLIB_CONSTANT_FLOAT64_MAX, -( n + 1 ) ) ) {
			return ( stdlib_base_signum( result ) == 1 ) ? STDLIB_CONSTANT_FLOAT64_PINF : STDLIB_CONSTANT_FLOAT64_NINF;
		}
		result *= stdlib_base_ldexp( 1.0, n + 1 ) - 1.0;
		return result;
	}

	return attransitionplus( n, x );
}